import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P02-1-Python-Starter-Journey/00-Newproject.html","title":"00-环境搭建&新建项目","lang":"zh-CN","frontmatter":{"title":"00-环境搭建&新建项目","icon":"yongyan","date":"2024-04-12T21:26:24.000Z","author":"AI悦创","isOriginal":true,"category":["Python notebook"],"tag":["Python 1v1"],"sticky":false,"star":false,"article":true,"timeline":true,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"watermark":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1753103278000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":33,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":3}],"changelog":[{"hash":"ccba48ce2a0079e71c7d992c41cd4b8507b74391","time":1753103278000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python-Programming-Course): 更新FAQ05和00-Newproject文档内容"},{"hash":"8bcd00ec0ef982a8c7b5b52bc97fc06693a8adfd","time":1753098488000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python-Programming-Course): 更新新项目文档中的环境配置表格"},{"hash":"6026615dbe0abba774d69eced7a3546fbfab675d","time":1753097970000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python编程课程): 更新文档结构并添加本地环境配置说明"},{"hash":"f69810ac92e9a73ad46cbb9437d2c2cf6f2e4f67","time":1748782468000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新侧边栏和文件夹名称"},{"hash":"1be89c61c43dbf2a52eb8788786dd8762187ce70","time":1748754865000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"P02-Python-Starter-Journey"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"4fe5e5aa9954038fad74e0bfabf1fb7f2a688790","time":1745911165000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增在线编程环境使用步骤及备用平台链接"},{"hash":"d79fc6328b80b09969f30c1e24d32eed8fe38852","time":1745909892000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"7131fc3c42815714bc4ed83deb1376d7f582a869","time":1745908184000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"1f8b7a199fadc925c8e15daceb06f8b77f08b85e","time":1745906515000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"457f06505ec9e4caccaaad26f217bdfcf6bcb53c","time":1745905772000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新环境搭建章节，增加运行测试、删除文件和新建文件夹的详细说明，提升用户体验"},{"hash":"c7160df1cace42c68dea45816e791e71638de111","time":1745905143000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新安装包和视频教程部分，简化内容并提供更清晰的安装指导"},{"hash":"a55359529796daf888b5029972714d9789bdb8ac","time":1745900147000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"3a27fce1207e225451fef8488b511ced7146387d","time":1745890328000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新安装指南，增加下载方式和浏览器推荐，调整章节编号"},{"hash":"f9e9727af614b54f34d23b78e9fdf8c2b02350b6","time":1745888684000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"97433f5e52487c04bad67294f20c4b0c5e248305","time":1717401228000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"watermark: true"},{"hash":"af03831165c87a774c4c48faff7f4ca8e1160bcf","time":1713272054000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"1"},{"hash":"3c1404fe9e9a6c84d49b79be28992c04a867f615","time":1713251714000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"a2fb2e47a0ce7e99ea892f3595992e03361b833d","time":1713251021000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"d062664e0079cc0a4b2be5e19ba0c45930e39770","time":1713250662000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"bisss"},{"hash":"7de6c963bc77e19c8ca3219dc6ab66177a390e6f","time":1712934062000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"运行deactivate命令可以退出当前的虚拟环境，回到系统的全局Python环境。"},{"hash":"3d60a046aebbc1190badbd8420b56e2a472a842f","time":1712932156000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"依赖管理：不同项目可能需要不同版本的库，虚拟环境可以避免版本冲突。 项目隔离：保持全局环境的干净整洁，每个项目都有自己的环境，不会互相影响。 易于复制：如果你想在另一台机器或者环境中复制你的项目，虚拟环境可以让这一过程变得简单，因为你可以很容易地重新创建一个一模一样的环境。"},{"hash":"c99dde7f39b3ead7aebc7a725aac595ababee661","time":1712931588000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"22"},{"hash":"764e52bc42c1be66c60ca17435d6896816c94dde","time":1712931242000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"9b57f5735735ca3f1a77f9806e9bda3c24037a3f","time":1712930695000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"1"},{"hash":"1cd6fab0615c3e868ac3233a5e6c495237d51540","time":1712929978000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"image-20240412215249022"},{"hash":"01f985515f2c3fabec64b44c46e4864551df9a6a","time":1712929027000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"111"},{"hash":"833067a7ac38c2840d35709473976cdac8261fa5","time":1712928574000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"<a href=\\"http://00-Newproject.md\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">00-Newproject.md</a>"},{"hash":"d2f6408645561f94a1456e9fdbbcf5759ad6dcdd","time":1675746146000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"优化"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.23,"words":2170},"filePathRelative":"column/Python-Programming-Course/P02-1-Python-Starter-Journey/00-Newproject.md"}`),a={name:`00-Newproject.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在前言中的“本书资源”也已经提到了，可以使用配套的在线编程网站进行编写代码，网站：<a href="https://codemark.bornforthis.cn/editor" target="_blank" rel="noopener noreferrer">https://codemark.bornforthis.cn/editor</a>。不过肯定还是会有人想要在电脑上安装 Python，这确实是推荐的。前期入门可以用我的平台，但是后期还是需要电脑有对应的编程环境。</p><p>这部分考虑到大部分有可能是零基础小白，书籍的安装教程有时会过时，所以查看此链接即可安装：<a href="https://bornforthis.cn/Books/04-BookResources/01-InstallationPackage.html" target="_blank" rel="noopener noreferrer">https://bornforthis.cn/Books/04-BookResources/01-InstallationPackage.html</a></p><p><s>但是下面的下载方式要学会，那才是原则。因为学会了，不用再依赖使用别人准备好的安装包安装，自己可以去官方网站下载最新的安装包。</s></p><h2 id="_0-使用在线编程环境" tabindex="-1"><a class="header-anchor" href="#_0-使用在线编程环境"><span>0. 使用在线编程环境</span></a></h2><p>使用在线编程环境就很简单了，推荐使用谷歌浏览器或者 Microsoft Edge 浏览器、火狐浏览器，其它浏览器都不推荐！</p><p>界面介绍：</p><figure><img src="/assets/image-20250429145738020-Bf9IrwLL.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>步骤：</strong></p><ol><li>电脑开机；</li><li>打开浏览器；</li><li>输入链接；</li><li>访问在线编程平台；</li><li>等待加载成功，就可以开始尽情的编写代码了！</li></ol><p>备用编程平台，还支持画图：<a href="https://bornforthis.cn/python/#/" target="_blank" rel="noopener noreferrer">https://bornforthis.cn/python/#/</a></p><h2 id="_1-本地编程环境配置" tabindex="-1"><a class="header-anchor" href="#_1-本地编程环境配置"><span>1. 本地编程环境配置</span></a></h2><h3 id="_1-1-网站搭建所需要的环境" tabindex="-1"><a class="header-anchor" href="#_1-1-网站搭建所需要的环境"><span>1.1 网站搭建所需要的环境</span></a></h3><ol><li><p><strong>Windows 所需环境</strong></p><table><thead><tr><th>序号</th><th>名称</th><th>链接</th><th>用途</th></tr></thead><tbody><tr><td>01</td><td>NodeJs</td><td><a href="https://nodejs.org/zh-cn/download" target="_blank" rel="noopener noreferrer">https://nodejs.org/zh-cn/download</a></td><td>负责网站本地运行</td></tr></tbody></table></li><li><p><strong>Mac 所需环境</strong></p><table><thead><tr><th>序号</th><th>名称</th><th>链接</th><th>用途</th></tr></thead><tbody><tr><td>01</td><td></td><td></td><td></td></tr></tbody></table></li></ol><h3 id="_1-2-python-代码所需要的环境" tabindex="-1"><a class="header-anchor" href="#_1-2-python-代码所需要的环境"><span>1.2 Python 代码所需要的环境</span></a></h3><ol><li><p><strong>Windows 所需环境</strong></p><table><thead><tr><th>序号</th><th>名称</th><th>链接</th><th>用途</th></tr></thead><tbody><tr><td>01</td><td>Clash Verge Rev</td><td><a href="https://github.com/clash-verge-rev/clash-verge-rev/releases" target="_blank" rel="noopener noreferrer">https://github.com/clash-verge-rev/clash-verge-rev/releases</a></td><td>代理</td></tr><tr><td>02</td><td>Python</td><td><a href="https://www.python.org/downloads/" target="_blank" rel="noopener noreferrer">https://www.python.org/downloads/</a></td><td>运行代码</td></tr><tr><td>03</td><td>Pycharm</td><td><a href="https://www.jetbrains.com/pycharm/download/" target="_blank" rel="noopener noreferrer">https://www.jetbrains.com/pycharm/download/</a></td><td>编写代码</td></tr><tr><td>04</td><td>Snipaste</td><td><a href="https://www.snipaste.com/" target="_blank" rel="noopener noreferrer">https://www.snipaste.com/</a></td><td>截图软件</td></tr><tr><td>05</td><td>语雀</td><td><a href="https://www.yuque.com/dashboard" target="_blank" rel="noopener noreferrer">https://www.yuque.com/dashboard</a></td><td>记笔记用</td></tr><tr><td>06</td><td></td><td></td><td></td></tr></tbody></table></li><li><p><strong>Mac 所需环境</strong></p><table><thead><tr><th>序号</th><th>名称</th><th>链接</th><th>用途</th></tr></thead><tbody><tr><td>01</td><td></td><td></td><td></td></tr></tbody></table></li></ol><h2 id="_1-打开-pycharm" tabindex="-1"><a class="header-anchor" href="#_1-打开-pycharm"><span>1. 打开 PyCharm</span></a></h2><figure><img src="/assets/image-20240412213036713-C-fxlgVB.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_2-设置项目相关信息" tabindex="-1"><a class="header-anchor" href="#_2-设置项目相关信息"><span>2. 设置项目相关信息</span></a></h2><figure><img src="/assets/image-20240412213324386-BMtSlyMz.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>最后点击 Create 即可。</p><h2 id="_3-创建项目之后的界面" tabindex="-1"><a class="header-anchor" href="#_3-创建项目之后的界面"><span>3. 创建项目之后的界面</span></a></h2><figure><img src="/assets/image-20240412214704214-v8qtV9EI.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_4-运行代码测试" tabindex="-1"><a class="header-anchor" href="#_4-运行代码测试"><span>4. 运行代码测试</span></a></h2><p>鼠标右键运行后，看见输出结果，则表明环境正常。</p><figure><img src="/assets/image-20240412215049917-DuJmNY0T.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_5-删除-main-py" tabindex="-1"><a class="header-anchor" href="#_5-删除-main-py"><span>5. 删除 <a href="http://main.py" target="_blank" rel="noopener noreferrer">main.py</a></span></a></h2><p>编程环境测试成功后，删除自动创建的 <a href="http://main.py" target="_blank" rel="noopener noreferrer">main.py</a> 即可。</p><figure><img src="/assets/image-20240412215249022-B5FtLJYY.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>删除时，会有提示，点击确认即可。</p><figure><img src="/assets/image-20240412215322696-Dc_Chh5r.png" alt="点击确认" tabindex="0" loading="lazy"><figcaption>点击确认</figcaption></figure><h2 id="_6-注意⚠️" tabindex="-1"><a class="header-anchor" href="#_6-注意⚠️"><span>6. 注意⚠️</span></a></h2><p>文件夹中的 <code>.venv</code> 文件夹不能操作，是当前 PyCharm 环境的配置文件夹。</p><p>操作有可能导致无法正常运行，就放着不动即可。</p><h2 id="_7-新建文件夹" tabindex="-1"><a class="header-anchor" href="#_7-新建文件夹"><span>7. 新建文件夹</span></a></h2><p>放在要新建的文件夹 <code>Coder</code> 上，鼠标右键操作：</p><figure><img src="/assets/image-20240412220339444-BbHXVYdQ.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>输入创建的文件夹名称，推荐使用英文命名。</p><figure><img src="/assets/image-20240412220428654-AdYigxu1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>下图即可看见创建成功：</p><figure><img src="/assets/image-20240412220446047-BCi1zs_k.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_8-新建代码文件" tabindex="-1"><a class="header-anchor" href="#_8-新建代码文件"><span>8. 新建代码文件</span></a></h2><p>在你想把代码放在哪个文件夹，在那个文件夹上面鼠标右键。</p><figure><img src="/assets/image-20240412221211614-DPuRPThS.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>输入要创建的 Python 代码文件名称：</p><figure><img src="/assets/image-20240412221322161-BVt8Ptoq.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>创建成功后，可以编写代码进行测试：</p><figure><img src="/assets/image-20240412221529870-B2gt5Kyr.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_9-重命名" tabindex="-1"><a class="header-anchor" href="#_9-重命名"><span>9. 重命名</span></a></h2><p>有时候，我们会需要重新命名文件夹或者代码文件，所以接下来带你操作文件、文件夹重命名。</p><figure><img src="/assets/image-20240412222607743-DO2wqKq9.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>输入要重新命名的的名称，不要动 <code>.py</code>：</p><figure><img src="/assets/image-20240412222629936-D1BQbt4y.png" alt="修改名称即可" tabindex="0" loading="lazy"><figcaption>修改名称即可</figcaption></figure><p>文件夹也是如法炮制！</p><h2 id="_10-几种常见的虚拟环境介绍" tabindex="-1"><a class="header-anchor" href="#_10-几种常见的虚拟环境介绍"><span>10. 几种常见的虚拟环境介绍</span></a></h2><h3 id="_10-1-介绍" tabindex="-1"><a class="header-anchor" href="#_10-1-介绍"><span>10.1 介绍</span></a></h3><p>在 Python 开发中，虚拟环境是一个非常重要的概念，它允许你为每个项目创建一个独立的环境，这样就可以在不同项目之间隔离依赖，避免版本冲突。想象一下，你有两个项目，一个需要 Django 2.0，而另一个需要 Django 3.0。</p><figure><img src="/assets/image-20250429140126431-BxLiSXpF.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20250429141328379-B9h6LSQs.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>如果没有虚拟环境，这两个版本的 Django 就会发生冲突「因为，是在同一台电脑同一个 Python 肯定会冲突」。就像你一台电脑只能安装一个 QQ 和微信一样，只能存在一个版本的 QQ 和微信，不能存在多个不同版本的 QQ 和微信。</p><p>虚拟环境就像是给每个项目提供了一个小盒子，这个盒子里面装着所有这个项目需要的东西，而且盒子之间是相互独立的。</p><h3 id="_10-2-为什么需要虚拟环境" tabindex="-1"><a class="header-anchor" href="#_10-2-为什么需要虚拟环境"><span>10.2 为什么需要虚拟环境？</span></a></h3><ul><li><strong>依赖管理</strong>：不同项目可能需要不同版本的库，虚拟环境可以避免版本冲突。</li><li><strong>项目隔离</strong>：保持全局环境的干净整洁，每个项目都有自己的环境，不会互相影响。</li><li><strong>易于复制</strong>：如果你想在另一台机器或者环境中复制你的项目，虚拟环境可以让这一过程变得简单，因为你可以很容易地重新创建一个一模一样的环境。</li></ul><h3 id="_10-3-几种常见的-python-虚拟环境管理工具" tabindex="-1"><a class="header-anchor" href="#_10-3-几种常见的-python-虚拟环境管理工具"><span>10.3 几种常见的 Python 虚拟环境管理工具</span></a></h3><ol><li><strong>venv</strong><ul><li><code>venv</code> 是 Python 自带的虚拟环境工具，从 Python 3.3 开始内置。</li><li>使用方法简单，可以通过简单的命令创建虚拟环境，然后激活环境并在其中安装依赖。</li><li>适合大多数基本的用途。</li></ul></li><li><strong>pipenv</strong><ul><li><code>pipenv</code> 是一个 Python 开发工作流的工具，它结合了 pip 和 venv 的功能。</li><li>它自动管理项目的虚拟环境，并且使用 <code>Pipfile</code> 和 <code>Pipfile.lock</code> 来替代传统的 <code>requirements.txt</code>，这样可以更清楚地定义项目依赖。</li><li>它还提供了依赖图的概览，让开发者可以很方便地看到依赖之间的关系。</li></ul></li><li><strong>conda</strong><ul><li><code>conda</code> 是一个开源的包、依赖和环境管理器，它支持 Python 项目，但也可以用于其他语言的项目。</li><li>Conda 更像是一个跨平台的工具，不仅能管理 Python 库，还能管理非 Python 的库。</li><li>它非常适合于处理复杂的科学计算项目，因为很多科学计算库在安装时有复杂的依赖。</li></ul></li></ol><p>虚拟环境在 Python 开发中扮演着非常重要的角色，无论是保持开发环境的清洁，还是管理不同项目之间的依赖冲突，都有着不可替代的作用。选择哪种虚拟环境工具，主要取决于项目需求和个人偏好。</p><h3 id="_10-4-如何使用这些虚拟环境工具" tabindex="-1"><a class="header-anchor" href="#_10-4-如何使用这些虚拟环境工具"><span>10.4 如何使用这些虚拟环境工具</span></a></h3><h4 id="_10-4-1-venv" tabindex="-1"><a class="header-anchor" href="#_10-4-1-venv"><span>10.4.1 venv</span></a></h4><ol><li>新建虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">python3</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -m</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> venv</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> myenv</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这条命令会在当前目录下创建一个名为 <code>myenv</code> 的虚拟环境目录。这个目录包含了 Python 的可执行文件，以及一个 <code>pip</code> 库的拷贝，可以用来安装其他包。</p><ol start="2"><li>激活虚拟环境</li></ol><ul><li>Windows:</li></ul><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">myenv\\Scripts\\activate</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>macOS/Linux:</li></ul><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;">source</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> myenv/bin/activate</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>激活虚拟环境后，你会在命令行前面看到虚拟环境的名字，这表示虚拟环境已经被激活。</p><ol start="3"><li>退出虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">deactivate</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行 <code>deactivate</code> 命令可以退出当前的虚拟环境，回到系统的全局 Python 环境。</p><h4 id="_10-4-2-pipenv" tabindex="-1"><a class="header-anchor" href="#_10-4-2-pipenv"><span>10.4.2 pipenv</span></a></h4><ol><li>新建虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pipenv</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> install</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在项目目录中运行这个命令，如果 <code>Pipfile</code> 存在，<code>pipenv</code> 会根据 <code>Pipfile</code> 来创建一个新的虚拟环境。如果不存在，它会创建一个新的 <code>Pipfile</code>。</p><ol start="2"><li>使用虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pipenv</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> shell</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这个命令会激活虚拟环境。<code>pipenv</code> 也支持通过 <code>pipenv run</code> 命令在虚拟环境中运行命令，而无需手动激活虚拟环境。</p><ol start="3"><li>退出虚拟环境</li></ol><p>如果你是通过 <code>pipenv shell</code> 进入的虚拟环境，可以通过 <code>exit</code> 命令或者 Ctrl+D（在大多数 Unix 系统中）来退出。</p><h4 id="_10-4-3-conda" tabindex="-1"><a class="header-anchor" href="#_10-4-3-conda"><span>10.4.3 conda</span></a></h4><ol><li>新建虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">conda</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> create</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --name</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> myenv</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> python=</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">3.8</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这个命令会创建一个名为 <code>myenv</code> 的新虚拟环境，其中安装了 Python 3.8 。<code>conda</code> 允许你在创建环境时指定安装包。</p><ol start="2"><li>激活虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">conda</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> activate</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> myenv</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>使用 <code>conda activate </code> 命令激活虚拟环境。激活后，你会在命令行提示符前看到环境的名字。</p><ol start="3"><li>退出虚拟环境</li></ol><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">conda</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> deactivate</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行 <code>conda deactivate</code> 可以退出当前的虚拟环境。</p><p>每种工具的命令都有自己的特点，但基本的流程是相似的：创建环境、激活环境、使用环境，最后退出环境。使用虚拟环境是一个好习惯，它能帮助你更有效地管理项目依赖和避免潜在的冲突。</p>`,99)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};